{
  "name": "是德科技 MSO-X/DSO-X 3000A 系列示波器",
  "name_en": "Keysight MSO-X/DSO-X 3000A Series Oscilloscope",
  "manufacturer": "Keysight Technologies",
  "description": "台式数字/混合信号示波器，用于采集、显示和分析电信号波形。它常用于实验室中的电路调试、时序分析、脉冲与频率测量、上升下降时间评估、占空比分析以及屏幕截图、波形导出和仪器设置保存。",
  "description_en": "A benchtop digital or mixed-signal oscilloscope used to capture, display, and analyze electrical waveforms. It is commonly used in laboratories for circuit debugging, timing analysis, pulse and frequency measurements, rise/fall time evaluation, duty-cycle analysis, as well as saving screenshots, exporting waveform data, and storing instrument setups.",
  "tag_hints": [
    "oscilloscope",
    "mixed-signal oscilloscope",
    "waveform acquisition",
    "timing analysis",
    "voltage measurement",
    "frequency measurement",
    "DVM mode",
    "screen capture"
  ],
  "actions": [
    {
      "action_name": "auto-setupSave",
      "description": "保存示波器当前设置到文件。",
      "description_en": "Save the oscilloscope's current setup to a file."
    },
    {
      "action_name": "auto-setupLoad",
      "description": "从文件恢复示波器设置。",
      "description_en": "Restore the oscilloscope setup from a file."
    },
    {
      "action_name": "auto-setupAutoscale",
      "description": "对指定通道执行自动缩放以优化波形显示。",
      "description_en": "Autoscale the selected channel or channels to optimize waveform display."
    },
    {
      "action_name": "auto-annotate",
      "description": "在示波器屏幕上添加文字标注。",
      "description_en": "Add a text annotation to the oscilloscope screen."
    },
    {
      "action_name": "auto-annotateColor",
      "description": "设置屏幕标注的颜色。",
      "description_en": "Set the color of the on-screen annotation."
    },
    {
      "action_name": "auto-annotateOff",
      "description": "关闭屏幕标注显示。",
      "description_en": "Turn off the on-screen annotation display."
    },
    {
      "action_name": "auto-channelLabel",
      "description": "为选定通道添加标签。",
      "description_en": "Add a label to the selected channel."
    },
    {
      "action_name": "auto-channelLabelOff",
      "description": "关闭通道标签显示。",
      "description_en": "Turn off channel label display."
    },
    {
      "action_name": "auto-polish",
      "description": "将测量结果格式化为易读的工程单位表示。",
      "description_en": "Format a measurement result into readable engineering units."
    },
    {
      "action_name": "auto-measureStatistics",
      "description": "读取当前测量统计信息。",
      "description_en": "Read the current measurement statistics."
    },
    {
      "action_name": "auto-measureBitRate",
      "description": "测量信号比特率。",
      "description_en": "Measure the signal bit rate."
    },
    {
      "action_name": "auto-measureBurstWidth",
      "description": "测量突发信号宽度。",
      "description_en": "Measure the burst width of the signal."
    },
    {
      "action_name": "auto-measureCounterFrequency",
      "description": "测量计数器频率。",
      "description_en": "Measure the counter frequency."
    },
    {
      "action_name": "auto-measurePosDutyCycle",
      "description": "测量正占空比。",
      "description_en": "Measure the positive duty cycle."
    },
    {
      "action_name": "auto-measureFallTime",
      "description": "测量下降时间。",
      "description_en": "Measure the fall time."
    },
    {
      "action_name": "auto-measureRiseTime",
      "description": "测量上升时间。",
      "description_en": "Measure the rise time."
    },
    {
      "action_name": "auto-measureFrequency",
      "description": "测量信号频率。",
      "description_en": "Measure the signal frequency."
    },
    {
      "action_name": "auto-measureNegDutyCycle",
      "description": "测量负占空比。",
      "description_en": "Measure the negative duty cycle."
    },
    {
      "action_name": "auto-measureFallEdgeCount",
      "description": "统计屏幕内下降沿数量。",
      "description_en": "Count the number of falling edges on screen."
    },
    {
      "action_name": "auto-measureFallPulseCount",
      "description": "统计屏幕内负脉冲数量。",
      "description_en": "Count the number of falling or negative pulses on screen."
    },
    {
      "action_name": "auto-measureNegPulseWidth",
      "description": "测量负脉冲宽度。",
      "description_en": "Measure the negative pulse width."
    },
    {
      "action_name": "auto-measureOvershoot",
      "description": "测量电压过冲百分比。",
      "description_en": "Measure the voltage overshoot percentage."
    },
    {
      "action_name": "auto-measurePreshoot",
      "description": "测量电压前冲百分比。",
      "description_en": "Measure the voltage preshoot percentage."
    },
    {
      "action_name": "auto-measureRiseEdgeCount",
      "description": "统计屏幕内上升沿数量。",
      "description_en": "Count the number of rising edges on screen."
    },
    {
      "action_name": "auto-measureRisePulseCount",
      "description": "统计屏幕内正脉冲数量。",
      "description_en": "Count the number of rising or positive pulses on screen."
    },
    {
      "action_name": "auto-measurePosPulseWidth",
      "description": "测量正脉冲宽度。",
      "description_en": "Measure the positive pulse width."
    },
    {
      "action_name": "auto-measurePeriod",
      "description": "测量信号周期。",
      "description_en": "Measure the signal period."
    },
    {
      "action_name": "auto-measureVoltAmplitude",
      "description": "测量电压幅度。",
      "description_en": "Measure the voltage amplitude."
    },
    {
      "action_name": "auto-measureVoltAverage",
      "description": "测量平均电压。",
      "description_en": "Measure the average voltage."
    },
    {
      "action_name": "auto-measureVoltRMS",
      "description": "测量直流均方根电压。",
      "description_en": "Measure the DC RMS voltage."
    },
    {
      "action_name": "auto-measureVoltBase",
      "description": "测量波形基线电压。",
      "description_en": "Measure the waveform base voltage."
    },
    {
      "action_name": "auto-measureVoltTop",
      "description": "测量波形顶部电压。",
      "description_en": "Measure the waveform top voltage."
    },
    {
      "action_name": "auto-measureVoltMax",
      "description": "测量最大电压。",
      "description_en": "Measure the maximum voltage."
    },
    {
      "action_name": "auto-measureVoltMin",
      "description": "测量最小电压。",
      "description_en": "Measure the minimum voltage."
    },
    {
      "action_name": "auto-measureVoltPP",
      "description": "测量峰峰值电压。",
      "description_en": "Measure the peak-to-peak voltage."
    },
    {
      "action_name": "auto-measureDVMacrms",
      "description": "以数字电压表模式测量交流均方根电压。",
      "description_en": "Measure AC RMS voltage in DVM mode."
    },
    {
      "action_name": "auto-measureDVMdc",
      "description": "以数字电压表模式测量直流电压。",
      "description_en": "Measure DC voltage in DVM mode."
    },
    {
      "action_name": "auto-measureDVMdcrms",
      "description": "以数字电压表模式测量直流均方根电压。",
      "description_en": "Measure DC RMS voltage in DVM mode."
    },
    {
      "action_name": "auto-measureDVMfreq",
      "description": "以数字电压表模式测量频率。",
      "description_en": "Measure frequency in DVM mode."
    },
    {
      "action_name": "auto-hardcopy",
      "description": "保存示波器屏幕图像到文件。",
      "description_en": "Save a screenshot of the oscilloscope display to a file."
    },
    {
      "action_name": "auto-waveform",
      "description": "导出指定通道的波形数据到文件。",
      "description_en": "Export waveform data from the selected channel to a file."
    }
  ]
}

